// Reaksiyon oyunu: LED yanınca butona olabildiğince hızlı bas.
const int LED_PIN = 12;
const int BUTON_PIN = 2;      // butonun öbür ucu GND'de; iç pull-up açık
const int BUZZER_PIN = 8;

const unsigned long EN_AZ_BEKLE = 2000;   // LED yanmadan önce en kısa bekleme (ms)
const unsigned long EN_COK_BEKLE = 5000;  // en uzun bekleme (ms)
const unsigned long TUR_ARASI = 2000;     // turlar arası bekleme (ms)
const unsigned long CEZA_ARASI = 1000;    // erken basıştan sonra bekleme (ms)
const unsigned long TITRESIM_MS = 50;     // buton sıçramasını yok sayma süresi
const int UYARI_HZ = 200;                 // erken basış sesi (Hz)
const int UYARI_MS = 300;                 // erken basış sesinin süresi

bool basili() {
  return digitalRead(BUTON_PIN) == LOW;
}

// Buton bırakılana kadar bekler; bırakınca sıçramayı da bekler.
void birakilmasiniBekle() {
  while (basili()) {}
  delay(TITRESIM_MS);
}

void setup() {
  Serial.begin(9600);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTON_PIN, INPUT_PULLUP);
  randomSeed(analogRead(A0));  // boştaki A0 pini her açılışta farklı bir başlangıç verir
  Serial.println("Reaksiyon oyunu");
}

void loop() {
  digitalWrite(LED_PIN, LOW);
  Serial.println("Hazir ol...");

  // 1. Rastgele bir süre bekle. Bu sırada basılırsa erken sayılır.
  unsigned long bekleme = random(EN_AZ_BEKLE, EN_COK_BEKLE + 1);
  unsigned long baslangic = millis();
  while (millis() - baslangic < bekleme) {
    if (basili()) {
      Serial.println("Erken! LED yanmadan bastin.");
      tone(BUZZER_PIN, UYARI_HZ, UYARI_MS);
      birakilmasiniBekle();
      delay(CEZA_ARASI);
      return;  // tur baştan başlar
    }
  }

  // 2. LED'i yak ve basışa kadar geçen süreyi ölç.
  digitalWrite(LED_PIN, HIGH);
  unsigned long yandi = millis();
  while (!basili()) {}
  unsigned long tepki = millis() - yandi;
  digitalWrite(LED_PIN, LOW);

  Serial.print("Tepki suresi: ");
  Serial.print(tepki);
  Serial.println(" ms");

  birakilmasiniBekle();
  delay(TUR_ARASI);
}
